<template>
  <div class="flex-direction-column">
    <div
      class="g-page-container-with-header"
      v-for="(config, index) in configDataList"
      :key="index"
    >
      <div class="container-header flex-space-between">
        <span class="title config">配置 {{ config.devName }}</span>
        <span class="title file-path">文件位置：{{ config.configFile }}</span>

        <!-- 顶部按钮：有“顺序多选参数”就显示【保存顺序】，否则显示【全部保存】 -->
        <div
          v-if="getOrderParam(config)"
          class="g-button save-all-btn"
          @click="handleSaveOrderForConfig(config)"
        >
          保存顺序
        </div>
        <div
          v-else
          class="g-button save-all-btn"
          @click="handleRefreshBatch(config)"
        >
          全部保存
        </div>
      </div>

      <div class="container-content">
        <!-- 按参数逐行渲染 -->
        <div
          class="g-kv-pair"
          v-for="(param, pIndex) in config.paramDataList"
          :key="pIndex"
        >
          <!-- 可排序config类型 -->
          <template v-if="isOrderParam(param)">
            <div class="value">{{ param.txt }}</div>
            <div class="value">{{ param.val }}</div>
            <div class="value" style="flex: 1; margin-right: 20px">
              <el-select
                v-model="selectMap[paramKey(config, param)]"
                multiple
                filterable
                clearable
                placeholder="请选择音频，按点击顺序决定播放顺序"
                style="width: 100%"
                @change="handleSelectionChange(config, param)"
                @remove-tag="handleSelectionChange(config, param)"
                @clear="handleSelectionChange(config, param)"
              >
                <el-option
                  v-for="opt in optionsMap[paramKey(config, param)] || []"
                  :key="opt"
                  :label="opt"
                  :value="opt"
                />
              </el-select>

              <div class="tips">先后选择顺序即播放顺序</div>

              <div
                v-if="(selectMap[paramKey(config, param)] || []).length"
                class="preview"
              >
                当前所选顺序：{{
                  (selectMap[paramKey(config, param)] || []).join(', ')
                }}
              </div>
            </div>
            <div class="g-button" @click="handleSaveOrder(config, param)">
              保存顺序
            </div>
          </template>

          <!-- 普通config类型 -->
          <template v-else>
            <div class="value">{{ param.txt }}</div>
            <div class="value">{{ param.val }}</div>
            <div class="value" style="flex: 1; margin-right: 20px">
              <el-select
                v-if="param.values"
                v-model="param.editValue"
                filterable
                clearable
                placeholder="请选择"
                style="width: 100%"
              >
                <el-option
                  v-for="option in param.values.split(',')"
                  :key="option.trim()"
                  :label="option.trim()"
                  :value="option.trim()"
                />
              </el-select>
              <el-input
                v-else
                v-model="param.editValue"
                class="editable-input"
                type="text"
              />
            </div>
            <div class="g-button" @click="handleRefreshRow(param, config)">
              保存
            </div>
          </template>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { useWslStore } from '@/store/modules/ws.js'
import { useCommand } from '@/hooks/useCommand.js'
import { ElMessage } from 'element-plus'
import { useConfigMerge } from '@/hooks/useConfigMerge'

const store = useWslStore()
const { received } = storeToRefs(store)
const { sendConfigData, sendSetSbusAudioList } = useCommand(store)

// 获取配置数据configDataList
const { configDataList } = useConfigMerge(
  computed(() => received.value?.statusData?.configDataList)
)

// 多选+顺序
const optionsMap = ref({}) // { [key]: string[] } 候选项，param.values
const selectMap = ref({}) // { [key]: string[] } 当前选择，按点击顺序

// ==== 工具函数 ====
// 该 param 是否为 multiselect & sortable 的特殊渲染
const isOrderParam = (param) => {
  const t = (param?.type || '').split(',').map((s) => s.trim().toLowerCase())
  return t.includes('multiselect') && t.includes('sortable')
}
// 生成唯一 key（一个 config 里可能有多个特殊参数），用来在 selectMap/optionsMap 里做索引
const paramKey = (config, param) => `${config.configFile}::${param.key}`

// 变成数组
const csvToList = (s) =>
  (s || '')
    .split(',')
    .map((x) => x.trim())
    .filter(Boolean)

// 把选择写回 editValue，让 useConfigMerge 在新推送时保住它
const syncSelectionToEditValue = (config, param, arr) => {
  const p = (config?.paramDataList || []).find((x) => x.key === param.key)
  if (p) p.editValue = arr.join(',')
}

// 处理后端每秒推送但不影响选择：
// - 每次推送都刷新 options（values）；
// - 只在本地该参数还没初始化时，才用 editValue 或 val 初始化选择；
// - 如果候选变化导致某些已选项消失，则仅过滤掉那部分，顺序不动；
// - 每次变更都把选择回写到 editValue（让 useConfigMerge 持久化当前选择）
watch(
  () => configDataList.value,
  (list) => {
    ;(list || []).forEach((cfg) => {
      ;(cfg.paramDataList || []).forEach((p) => {
        if (!isOrderParam(p)) return
        const key = paramKey(cfg, p)

        // 1. 刷新候选
        const latestOptions = csvToList(p.values)
        optionsMap.value[key] = latestOptions

        // 2. 初始化选择（只做一次）
        if (!selectMap.value[key]) {
          // 默认空顺序
          selectMap.value[key] = []
          syncSelectionToEditValue(cfg, p, [])
          return
        }

        // 3. 已初始化：与候选对齐（移除无效项，保留原顺序）
        const current = selectMap.value[key]
        const filtered = current.filter((v) => latestOptions.includes(v))
        if (filtered.length !== current.length) {
          selectMap.value[key] = filtered
          syncSelectionToEditValue(cfg, p, filtered)
        }
      })
    })
  },
  { immediate: true }
)

// el-select 变化时调用：合法化 + 回写同步到 editValue
const handleSelectionChange = (config, param) => {
  const key = paramKey(config, param)
  const options = optionsMap.value[key] || []
  const arr = (selectMap.value[key] || []).filter((v) => options.includes(v))
  selectMap.value[key] = arr
  syncSelectionToEditValue(config, param, arr)
}

//保存顺序（按选择顺序拼 CSV 下发命令）
const handleSaveOrder = (config, param) => {
  const key = paramKey(config, param)
  const arr = selectMap.value[key] || []
  if (arr.length === 0) {
    ElMessage.warning('请先选择至少一个音频')
    return
  }
  const audioListStr = arr.join(',')
  // console.log('audioListStr:' + audioListStr)
  sendSetSbusAudioList(audioListStr)
}

// “保存顺序”按钮，需快速取到该 config 里的第一个顺序多选参数：
const getOrderParam = (config) =>
  (config?.paramDataList || []).find(isOrderParam)
const handleSaveOrderForConfig = (config) => {
  const p = getOrderParam(config)
  if (p) handleSaveOrder(config, p)
}

// 监听设备控制回包
const isCmdDeviceControl = (cmd) =>
  cmd === 49 || cmd === 'CMD_RUN_DEVICE_CONTROL'
const isSuccess = (code) => code === 0 || code === 'ERROR_CODE_SUCCESS'
watch(
  () => received.value,
  (resp) => {
    if (!resp) return
    if (!isCmdDeviceControl(resp.command)) return

    if (isSuccess(resp.errorCode)) {
      ElMessage.success('操作成功')
    } else {
      ElMessage({
        type: 'error',
        message: resp.errorMessage || '操作失败',
        duration: 0,
        showClose: true
      })
    }
  },
  { deep: true }
)

// 普通配置：单行保存
const handleRefreshRow = (param, config) => {
  const newVal = param.editValue?.trim()

  if (!newVal) {
    ElMessage.error(`参数 ${param.key} 的值不能为空`)
    return
  }

  // 根据 param.type 判断是否校验为数字
  if (param.type === 'number' && isNaN(Number(newVal))) {
    ElMessage.error(`参数 ${param.key} 必须为数字`)
    return
  }

  if (param.val !== newVal) {
    sendConfigData(config.devName, config.configFile, [
      { key: param.key, val: newVal }
    ])
    ElMessage.success(`已保存参数 ${param.key} = ${newVal}`)
  } else {
    ElMessage.warning('该参数未发生变更，无需保存')
  }
}

// 普通配置：批量保存
const handleRefreshBatch = (config) => {
  const emptyParams = []
  const nonNumberParams = []

  config.paramDataList.forEach((p) => {
    const val = p.editValue?.trim()
    if (!val) {
      emptyParams.push(p.key)
    } else if (p.type === 'number' && isNaN(Number(val))) {
      nonNumberParams.push(p.key)
    }
  })

  if (emptyParams.length > 0) {
    ElMessage.error(
      `请填写 ${config.devName} 的参数：${emptyParams.join('、')}`
    )
    return
  }

  if (nonNumberParams.length > 0) {
    ElMessage.error(
      `参数 ${config.devName} 中以下项必须为数字：${nonNumberParams.join('、')}`
    )
    return
  }

  const changedParams = config.paramDataList
    .filter((p) => p.val !== p.editValue?.trim())
    .map((p) => ({ key: p.key, val: p.editValue.trim() }))

  if (changedParams.length > 0) {
    sendConfigData(config.devName, config.configFile, changedParams)
    ElMessage.success(
      `已批量保存 ${config.devName} 的 ${changedParams.length} 个修改项`
    )
  } else {
    ElMessage.warning('该配置未发生变更，无需全部保存')
  }
}
</script>

<style lang="less" scoped>
.save-all-btn {
  background-color: #90c2ff;
  color: #fff;
}

.container-header {
  .config {
    width: 29%;
  }
  .file-path {
    width: 60%;
  }
}
</style>
