// 一句话简述：专用于配置/config页面（特定数据结构，有editValue）合并更新单行or勾选行数据与未更新的数据行（useDataMerge.js的变体之专用于config页面版）

/**
 * useConfigMerge
 * 目的：用于「配置页（/config）」在后端持续推送时，**保住用户正在编辑的值(editValue)**，并把局部更新安全合并到上一帧。
 *
 * 工作方式：
 *  - 以 (devName + configFile) 为条目主键，遍历合并每个条目的 paramDataList；
 *  - 同 key 的参数按 **深合并**：来自新推送的字段覆盖，但 **editValue 优先保留旧值**（若旧值存在，否则用新值的 val 作为初始 editValue）；
 *  - 若后端暂无数据，给出“暂无”占位结构，避免空渲染；
 *  - 返回一个 computed：`configDataList`，供页面直接渲染并支持单行/批量保存，**不会因增量回包丢失当前编辑**。
 *
 * 区别：这是 useDataMerge.js 的「配置页专用变体」，面向带 paramDataList/editValue 的层级数据做深合并与编辑态持久化。
 */

import { ref, watch, computed } from 'vue'

export function useConfigMerge(rawListRef) {
  const lastList = ref([])

  watch(
    rawListRef,
    (newList) => {
      if (!newList || newList.length === 0) {
        lastList.value = [
          {
            devName: '暂无',
            configFile: '暂无',
            paramDataList: [
              {
                key: 'empty1',
                txt: '暂无参数',
                val: '暂无可单选数据',
                editValue: '',
                values: '1,2'
              },
              {
                key: 'empty2',
                txt: '暂无参数',
                val: '暂无可填写数据',
                editValue: ''
              }
            ]
          }
        ]
        return
      }

      const oldList = lastList.value

      // 深层 merge，保住 editValue
      const mergedList = newList.map((newItem) => {
        const oldItem = oldList.find(
          (o) =>
            o.devName === newItem.devName && o.configFile === newItem.configFile
        )

        const newParams = newItem.paramDataList || []
        const oldParams = oldItem?.paramDataList || []

        const mergedParams = newParams.map((newParam) => {
          const oldParam = oldParams.find((p) => p.key === newParam.key)
          return {
            ...newParam,
            editValue:
              oldParam?.editValue !== undefined
                ? oldParam.editValue
                : newParam.val ?? ''
          }
        })

        return {
          ...newItem,
          paramDataList: mergedParams
        }
      })

      lastList.value = mergedList
    },
    { immediate: true }
  )

  return {
    configDataList: computed(() => lastList.value)
  }
}
